#!/bin/bash
# Generated by reef-eval's EdgeBench converter. Runs in the SEPARATE verifier
# container (built from the judge image). Harbor re-materializes the declared
# submission artifacts at their original paths before this script runs; the
# checks below just make a missing submission loud.
set -uo pipefail
mkdir -p /logs/verifier

[ -e "/home/workspace/jagua-rs/lbf/src" ] || echo "WARNING: submission missing: /home/workspace/jagua-rs/lbf/src"
[ -e "/home/workspace/jagua-rs/jagua-rs/src" ] || echo "WARNING: submission missing: /home/workspace/jagua-rs/jagua-rs/src"
[ -e "/home/workspace/jagua-rs/lbf/Cargo.toml" ] || echo "WARNING: submission missing: /home/workspace/jagua-rs/lbf/Cargo.toml"
[ -e "/home/workspace/jagua-rs/jagua-rs/Cargo.toml" ] || echo "WARNING: submission missing: /home/workspace/jagua-rs/jagua-rs/Cargo.toml"
[ -e "/home/workspace/jagua-rs/Cargo.toml" ] || echo "WARNING: submission missing: /home/workspace/jagua-rs/Cargo.toml"

cd /home/workspace/jagua-rs
OUT=$(cd /home/workspace/jagua-rs && JAGUA_EVAL_CASES=16 JAGUA_EVAL_SAMPLES=900 JAGUA_CASE_TIMEOUT=20 JAGUA_BUILD_TIMEOUT=300 CANDIDATE_ROOT=/home/workspace/jagua-rs REFERENCE_ROOT=/home/workspace/jagua-rs-ref bash /home/workspace/jagua_task_scorer/score.sh 2>&1)
EC=$?
echo "$OUT" | tail -40
printf '%s' "$OUT" | python3 /tests/parse_score.py
echo "eval exit code: $EC" > /logs/verifier/eval_exit_code.txt
